# Existing announcements, mapped explicitly by course slug to the external
# key of the cohort they were written for. On 16 Nov 2026 production had
# three announcements, all on ai-buildcamp and all for Cohort 4 (ids 1-3:
# study groups, Session 9 cancellation, project submission).
EXPLICIT_COHORT_KEYS = {
    'ai-buildcamp': '4',
}


def map_announcements_to_cohorts(apps, schema_editor):
    """Assign each existing announcement a cohort without sending email.

    Uses ``QuerySet.update`` only: no ``save()``, no signals, no publish
    path, and ``email_queued_at`` is left untouched, so nothing is re-sent.
    Rows of courses outside ``EXPLICIT_COHORT_KEYS`` get the dated cohort
    running on their publish (or creation) date; a row with no such cohort
    stays unassigned, which hides it from learners and never emails.
    """
    CourseAnnouncement = apps.get_model('content', 'CourseAnnouncement')
    Cohort = apps.get_model('content', 'Cohort')
    rows = CourseAnnouncement.objects.filter(cohort__isnull=True).select_related(
        'course',
    )
    for announcement in rows:
        cohort = None
        key = EXPLICIT_COHORT_KEYS.get(announcement.course.slug)
        if key is not None:
            cohort = Cohort.objects.filter(
                course_id=announcement.course_id, external_key__iexact=key,
            ).first()
        if cohort is None:
            moment = announcement.published_at or announcement.created_at
            cohort = Cohort.objects.filter(
                course_id=announcement.course_id,
                mode='cohort',
                start_date__lte=moment.date(),
                end_date__gte=moment.date(),
            ).order_by('-start_date', '-pk').first()
        if cohort is not None:
            CourseAnnouncement.objects.filter(pk=announcement.pk).update(
                cohort=cohort,
            )


